 // Keep the oscillator's current source/view intact while editing voice count.
 void bindUnisonPreview(juce::Component::SafePointer<SynthGraph> graph){
 slider.onDragStart=[graph]{if(graph)graph->setDetunePreview(true);};
 slider.onDragEnd=[graph]{if(graph)graph->setDetunePreview(false);};
 slider.onValueChange=[graph]{if(graph&&graph->isDetunePreview())graph->repaint();};
 for(auto* arrow:{unisonUp.get(),unisonDown.get()})if(arrow){arrow->setTriggeredOnMouseDown(true);arrow->onStateChange=[this,graph]{if(graph)graph->setDetunePreview(unisonUp->isDown()||unisonDown->isDown());};}
 }
 void refreshMacroLabel(){if(macroIndex<0)return;auto state=processor.macros();if(macroIndex>=(int)state->names.size())return;if(extraParameter&&!slider.isMouseButtonDown())slider.setValue(extraParameter->get(),juce::dontSendNotification);auto name=state->names[macroIndex];label.setText(name.isEmpty()?"MACRO "+juce::String(macroIndex+1):name,juce::dontSendNotification);label.setColour(juce::Label::textColourId,juce::Colour(state->colours[macroIndex]));label.setTooltip(name+" / Number: name and colour. Drag the link count onto a knob.");}
