 void resized()override{if(envRow){label.setBounds(0,getHeight()-16,getWidth(),16);slider.setTextBoxStyle(juce::Slider::TextBoxAbove,false,getWidth(),24);slider.setBounds(0,0,getWidth(),getHeight()-16);}else if(warpRow){slider.setBounds(0,12,getWidth(),34);label.setBounds(0,49,getWidth(),11);}else if(moduleRow){label.setBounds(0,0,getWidth(),12);if(unisonField){slider.setBounds(0,18,getWidth()-12,22);unisonUp->setBounds(getWidth()-11,18,11,11);unisonDown->setBounds(getWidth()-11,29,11,11);}else slider.setBounds(0,12,getWidth(),getHeight()-12);}else if(macroIndex>=0){label.setBounds(0,getHeight()-15,getWidth(),15);slider.setBounds(6,1,getWidth()-35,getHeight()-17);macroHandle->setBounds(getWidth()-26,1,25,getHeight()-17);}else if(phaseStrip||tuningStrip){int caption=tuningStrip?22:getComponentID().endsWith("random")?55:24;label.setBounds(0,0,caption,getHeight());slider.setTextBoxStyle(juce::Slider::TextBoxLeft,false,getWidth()-caption-2,getHeight()-2);slider.setBounds(caption,1,getWidth()-caption-1,getHeight()-2);}else if(stripField){label.setBounds(0,0,40,getHeight());slider.setBounds(41,1,getWidth()-42,getHeight()-2);}else if(unisonField){int caption=getHeight()<30?0:14;int inset=getHeight()<30?35:0;label.setBounds(0,getHeight()<30?0:getHeight()-caption,getHeight()<30?35:getWidth(),getHeight()<30?getHeight():caption);int y=(getHeight()-caption-22)/2;slider.setBounds(inset,y,getWidth()-12-inset,22);unisonUp->setBounds(getWidth()-11,y,11,11);unisonDown->setBounds(getWidth()-11,y+11,11,11);}else if(inlineTune){int labelWidth=getComponentID().endsWith("loopStart")||getComponentID().endsWith("loopEnd")?14:getWidth()<65?22:29;label.setBounds(0,0,labelWidth,getHeight());slider.setBounds(labelWidth+2,(getHeight()-21)/2,getWidth()-labelWidth-4,21);}else if(bottomLabel){label.setBounds(0,getHeight()-14,getWidth(),14);slider.setBounds(0,0,getWidth(),getHeight()-14);}else{label.setBounds(0,0,getWidth(),12);slider.setBounds(0,12,getWidth(),getHeight()-12);}}
 void refreshEnvelopeMode(){if(envParameter.isEmpty())return;auto prefix=envParameter.substring(0,4);bool sustain=envParameter.endsWith("s");int sync=!sustain&&processor.value(prefix+"sync")>.5f?1:0;if(sync==envelopeSync)return;if(slider.isMouseButtonDown())return;envelopeSync=sync;attachment.reset();attachment=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(processor.state,envParameter+(sync?"Beat":""),slider);slider.bindAutomation(processor.state.getParameter(envParameter+(sync?"Beat":"")),&processor);if(sync){slider.textFromValueFunction=[](double value){return envelopeBeatNames()[juce::jlimit(0,22,(int)std::round(value))];};slider.valueFromTextFunction=[](const juce::String& text){int at=envelopeBeatNames().indexOf(text.trim());return at>=0?(double)at:text.getDoubleValue();};}else if(sustain){slider.textFromValueFunction=[](double value){return juce::String(value*100,0)+"%";};slider.valueFromTextFunction=[](const juce::String& text){return text.getDoubleValue()/100;};}else{slider.textFromValueFunction=[](double value){return value<1?juce::String(value*1000,0)+"ms":juce::String(value,2)+"s";};slider.valueFromTextFunction=[](const juce::String& text){return text.containsIgnoreCase("ms")?text.getDoubleValue()/1000:text.getDoubleValue();};}slider.updateText();}
 void setEnvelopeRow(juce::String parameter){envRow=true;envParameter=parameter;slider.setColour(juce::Slider::textBoxTextColourId,nd::colour(juce::Colour(NEXUM_UI_ACCENT)));slider.setColour(juce::Slider::textBoxBackgroundColourId,juce::Colours::transparentBlack);slider.setColour(juce::Slider::textBoxOutlineColourId,juce::Colours::transparentBlack);refreshEnvelopeMode();resized();}
 void useWarpRow(juce::String name){warpRow=true;label.setText(name,juce::dontSendNotification);slider.setTextBoxStyle(juce::Slider::NoTextBox,false,0,0);slider.setPopupDisplayEnabled(true,true,this);resized();}
 void alignModuleRow(){if(warpRow)return;moduleRow=true;if(!unisonField)slider.setTextBoxStyle(juce::Slider::TextBoxBelow,false,49,14);resized();}
