 void noiseMenu(){using namespace juce;PopupMenu menu;menu.addSectionHeader("NOCTRL / 20 NOISE TEXTURES");auto names=noisePresetNames();auto assets=std::atomic_load(&p.importedAssets);String current=assets&&assets->expansion?assets->expansion->noiseName:String();for(int i=0;i<names.size();++i)menu.addItem(i+1,names[i],true,current.contains("NoCTRL Noise - "+names[i]+".wav"));menu.addSeparator();menu.addItem(100,"Load noise WAV...");auto safe=Component::SafePointer<OscPage>(this);menu.showMenuAsync(PopupMenu::Options().withTargetComponent(assetButtons[3]),[safe](int selected){if(!safe||selected==0)return;if(selected==100)safe->loadAsset(3);else{String error;if(!safe->p.loadNoisePreset(selected-1,error))AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Noise",error);safe->timerCallback();}});}
